/**
 * Copies the compiled DevMatch contract module and its ZK assets from
 * ../contracts/managed/dev_profile into this frontend so Vite can bundle and
 * serve them.
 *
 * Run via `npm run prepare:contract` (auto-runs before dev/build).
 * The source artifacts are generated by `npm run compile` at the repo root.
 */
import { cpSync, existsSync, mkdirSync, rmSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const frontend = join(here, '..');
const managed = join(frontend, '..', 'contracts', 'managed', 'dev_profile');

const contractSrc = join(managed, 'contract');
const zkirSrc = join(managed, 'zkir');
const keysSrc = join(managed, 'keys');

const contractDest = join(frontend, 'src', 'generated', 'contract');
const zkDest = join(frontend, 'public', 'zk');

if (!existsSync(managed)) {
  console.error(
    '\n❌ contracts/managed/dev_profile not found.\n' +
      '   Run `npm run compile` at the repo root first.\n',
  );
  process.exit(1);
}

// Compiled contract module -> src/generated/contract
rmSync(contractDest, { recursive: true, force: true });
mkdirSync(contractDest, { recursive: true });
cpSync(contractSrc, contractDest, { recursive: true });

// ZKIR + proving/verifying keys -> public/zk/{zkir,keys}
rmSync(zkDest, { recursive: true, force: true });
mkdirSync(join(zkDest, 'zkir'), { recursive: true });
mkdirSync(join(zkDest, 'keys'), { recursive: true });
cpSync(zkirSrc, join(zkDest, 'zkir'), { recursive: true });
cpSync(keysSrc, join(zkDest, 'keys'), { recursive: true });

console.log('✔ Contract + ZK assets copied into frontend (src/generated, public/zk)');
